insert into public.quest_templates (id, family_id, version, category, intensity, title, content, published) values
('day_pitch_swap_bold_v1', 'day_pitch_swap', 1, 'daytime', 'bold', 'The Two-Person Pitch Swap', '{"id":"day_pitch_swap_bold_v1","familyId":"day_pitch_swap","version":1,"category":"daytime","intensity":"bold","title":"The Two-Person Pitch Swap","hook":"You have ten minutes to turn an ordinary object into a ridiculous invention. Then your partner changes the brief.","durationMinutes":45,"minParticipants":2,"maxParticipants":2,"cost":{"minMinor":0,"maxMinor":0,"currency":"USD","scope":"total","venueCostUnknown":true,"note":"Free with two ordinary objects and paper you already own. The 45 minutes includes choosing props, preparing, two pitches, and the verdict. Optional travel is added separately."},"settings":["home","outside"],"interests":["comedy","making","absurd","competitive"],"roles":["main_character","camera_person","rotate"],"preparation":"a_few_things","conflicts":[],"venuePermissionRequired":true,"arrangementRequired":false,"adultOnly":false,"supportsAdultContext":false,"requiresVolunteer":false,"beats":[{"label":"Setup","action":"Spend ten minutes inventing a harmless new use for your object. Agree two playful prompt cards, such as ‘now pitch it to a penguin’ or ‘explain it as a weather forecast’. Each person may veto a prompt before filming.","filming":"Film the ordinary props, preparation, and each person''s confident prediction.","caption":"Setup"},{"label":"The Moment","action":"Take turns delivering a one-minute pitch while the other films or listens. Halfway through, the listener reveals one approved prompt. Keep going in the new style for twenty seconds, then swap roles.","filming":"Record the prompt reveal and the performer''s genuine attempt to adapt, with their permission.","caption":"The Moment"},{"label":"Payoff","action":"Reveal the original objects and give each invention one sincere compliment and one obviously silly award. Failed improvisation is a valid ending; nobody has to repeat a take.","filming":"Capture the two objects, your invented awards, and the pair''s real verdict.","caption":"Payoff"}],"materials":["Two safe ordinary objects already owned","Paper or phone notes","Two willing pitch partners"],"completionQuestions":["Did both people deliver a one-minute pitch and respond to the agreed surprise prompt? A pitch falling apart counts.","Did everyone shown agree to being recorded, or did you use your own props and an honest private recap?","Did you make the agreed attempt without pressuring anyone to continue?"],"fallback":"Stay at home and use a mug or folded paper. If performing on camera is uncomfortable, record the objects and give an honest recap after the live attempt.","requirements":["Two willing people use a space they are allowed to use. No audience, outside cast, purchase, or advance booking is required.","Pitch invented uses for ordinary objects; no real product claims, private disclosures, risky demonstrations, or filming of bystanders."],"award":{"xp":250,"points":25},"cooldownDays":30}'::jsonb, true),
('day_tiny_discovery_chill_v1', 'day_tiny_discovery', 1, 'daytime', 'chill', 'Three Things You Never Noticed', '{"id":"day_tiny_discovery_chill_v1","familyId":"day_tiny_discovery","version":1,"category":"daytime","intensity":"chill","title":"Three Things You Never Noticed","hook":"A tiny expedition through a familiar place, with three details you usually walk past.","durationMinutes":30,"minParticipants":1,"maxParticipants":2,"cost":{"minMinor":0,"maxMinor":0,"currency":"USD","scope":"total","venueCostUnknown":true,"note":"No purchase needed. The 30 minutes includes choosing a small accessible area, looking for details, and filming a short personal verdict. Optional travel is additional."},"settings":["home","outside"],"interests":["local_knowledge","making","spontaneous"],"roles":["mastermind","camera_person","rotate"],"preparation":"start_now","conflicts":[],"venuePermissionRequired":true,"arrangementRequired":false,"adultOnly":false,"supportsAdultContext":false,"requiresVolunteer":false,"beats":[{"label":"Setup","action":"Choose one room or a small familiar outdoor area. Set a fifteen-minute observation window and name three things to look for: an interesting texture, a sign of change, and an overlooked object.","filming":"Film yourself naming the three clues, or show a handwritten clue list.","caption":"Setup"},{"label":"The Moment","action":"Find one real detail for each clue. Stay within your chosen area and film only things you are allowed to show. If with a partner, each contributes at least one discovery.","filming":"Capture a close-up of the discovery you almost missed and explain why it caught your attention.","caption":"The Moment"},{"label":"Payoff","action":"Choose the most surprising discovery and explain how you had overlooked it. An ordinary detail with an honest explanation is enough.","filming":"Record your final discovery and a short genuine verdict on your tiny expedition.","caption":"Payoff"}],"materials":["Your phone","A familiar room or small accessible outdoor area"],"completionQuestions":["Did you find three genuine details and explain which one surprised you most?","Did everyone shown agree to being recorded, or did you use your own props and an honest private recap?","Did you make the agreed attempt without pressuring anyone to continue?"],"fallback":"Do the entire trail in one room: a texture, a forgotten object, and a patch of light all count. Remain stationary if walking is unsuitable.","requirements":["Stay in your home or an outdoor area you are allowed to access. No entry into private property, purchases, or conversations with strangers are required.","Film objects and textures, avoiding identifiable bystanders, house numbers, private documents, and location clues you do not want to share."],"award":{"xp":100,"points":10},"cooldownDays":30}'::jsonb, true),
('night_pocket_radio_bold_v1', 'night_pocket_radio', 1, 'late_night', 'bold', 'The Living-Room Radio Show', '{"id":"night_pocket_radio_bold_v1","familyId":"night_pocket_radio","version":1,"category":"late_night","intensity":"bold","title":"The Living-Room Radio Show","hook":"A news desk for extremely ordinary events. Your cohost has one approved interruption up their sleeve.","durationMinutes":45,"minParticipants":2,"maxParticipants":4,"cost":{"minMinor":0,"maxMinor":0,"currency":"USD","scope":"total","venueCostUnknown":true,"note":"Free with household props and phone notes. The 45 minutes includes writing, a rehearsal, a short live attempt, and the closing verdict. No venue or advance arrangements are needed."},"settings":["home"],"interests":["comedy","music","absurd","friendly_awkward"],"roles":["main_character","camera_person","rotate"],"preparation":"a_few_things","conflicts":[],"venuePermissionRequired":true,"arrangementRequired":false,"adultOnly":false,"supportsAdultContext":false,"requiresVolunteer":false,"beats":[{"label":"Setup","action":"Spend fifteen minutes making an original show: a dramatic report about an ordinary household event, an absurd weather update, and a quiet invented jingle. Agree a harmless surprise prompt and let everyone veto topics.","filming":"Film the hosts preparing the title and rehearsing their over-serious introductions.","caption":"Setup"},{"label":"The Moment","action":"Perform the one-minute show in a single live attempt. Hand off to your cohost, who reveals the approved prompt. Improvise for twenty seconds and bring the show back on track without starting again.","filming":"Capture the live handoff, prompt reveal, and genuine attempt to keep the show together.","caption":"The Moment"},{"label":"Payoff","action":"Close the fictional show, break character, and name its best accidental moment. Nobody needs to act more embarrassed or repeat a reaction.","filming":"Film the hosts'' immediate verdict or your own honest recap beside the homemade title.","caption":"Payoff"}],"materials":["Two to four willing hosts","A handwritten show title","Phone notes and quiet household sound-effect props"],"completionQuestions":["Did you perform a short original show with a live handoff and respond to the agreed prompt? Awkward pauses count.","Did everyone shown agree to being recorded, or did you use your own props and an honest private recap?","Did you make the agreed attempt without pressuring anyone to continue?"],"fallback":"Use quiet voices and tabletop sound effects. Film the homemade show title and record your own recap if a partner prefers to stay off camera.","requirements":["Everyone agrees to a short private performance. This is a fictional show recorded at home, not an actual public broadcast or a prank call.","Use your own spoken words and sound effects. No commercial music, private disclosures, impersonation of real emergency services, or loud late-night noise."],"award":{"xp":250,"points":25},"cooldownDays":30}'::jsonb, true)
